INSERT INTO Vacuna (Nombre, componentes, objetivo, Especie) VALUES 
('Antirrabica canina', 'Antigeno de rabia inactivado, medio de cultivo, agente inactivador y excipientes.', 'Previene la rabia en perros.', 'Perro'),
('Polivalente', 'Antigenos de moquillo, adenovirus, parvovirus y parainfluenza, segun formulacion.', 'Protege contra varias enfermedades infecciosas frecuentes en perros.', 'Perro'),
('Moquillo', 'Antigeno del virus del moquillo canino atenuado o inactivado, segun formulacion.', 'Previene el moquillo canino.', 'Perro'),
('Parvovirus', 'Antigeno del parvovirus canino, generalmente vivo modificado.', 'Previene la infeccion por parvovirus canino.', 'Perro'),
('Adenovirus', 'Antigeno de adenovirus canino, generalmente vivo modificado.', 'Ayuda a prevenir la hepatitis infecciosa canina.', 'Perro'),
('Parainfluenza', 'Antigeno del virus de parainfluenza canina.', 'Ayuda a prevenir enfermedades respiratorias asociadas a parainfluenza.', 'Perro'),
('Leptospirosis', 'Antigenos inactivados de diferentes serovares de Leptospira y adyuvantes.', 'Ayuda a prevenir la leptospirosis en perros.', 'Perro'),
('Bordetella', 'Antigenos de Bordetella bronchiseptica, segun formulacion.', 'Ayuda a prevenir enfermedades respiratorias infecciosas en perros.', 'Perro'),
('Leishmaniosis', 'Antigenos o componentes antigenicos relacionados con Leishmania, segun producto.', 'Ayuda a reducir el riesgo de leishmaniosis canina en zonas donde esta indicada.', 'Perro'),
('Antirrabica ', 'Antigeno de rabia inactivado, medio de cultivo, agente inactivador y excipientes.', 'Previene la rabia en gatos.', 'Gato'),
('Triple ', 'Antigenos de herpesvirus felino, calicivirus felino y panleucopenia felina.', 'Previene enfermedades virales frecuentes en gatos.', 'Gato'),
('Herpesvirus', 'Antigeno del herpesvirus felino tipo 1, segun formulacion.', 'Ayuda a prevenir la rinotraqueitis viral felina.', 'Gato'),
('Calicivirus', 'Antigeno del calicivirus felino, segun formulacion.', 'Ayuda a prevenir la enfermedad causada por calicivirus felino.', 'Gato'),
('Panleucopenia', 'Antigeno del virus de la panleucopenia felina.', 'Previene la panleucopenia felina.', 'Gato'),
('Leucemia', 'Antigenos relacionados con el virus de la leucemia felina y componentes auxiliares.', 'Ayuda a prevenir la infeccion por el virus de la leucemia felina en gatos con riesgo de exposicion.', 'Gato'),
('Mixomatosis', 'Componentes antigenicos relacionados con el virus de la mixomatosis, segun formulacion.', 'Previene o reduce el riesgo de mixomatosis en conejos.', 'Conejo'),
('Enfermedad hemorragica viral', 'Antigenos del virus de la enfermedad hemorragica del conejo.', 'Previene la enfermedad hemorragica viral del conejo.', 'Conejo'),
('Newcastle aviar', 'Antigenos del virus de Newcastle, vivos modificados o inactivados segun formulacion.', 'Previene la enfermedad de Newcastle en aves susceptibles.', 'Ave'),
('Bronquitis infecciosa aviar', 'Antigenos del coronavirus de la bronquitis infecciosa aviar.', 'Previene o reduce la enfermedad respiratoria causada por bronquitis infecciosa aviar.', 'Ave'),
('Viruela aviar', 'Virus de la viruela aviar atenuado.', 'Previene la viruela aviar.', 'Ave'),
('Marek aviar', 'Herpesvirus aviar atenuado o componentes antigenicos de la vacuna.', 'Previene la enfermedad de Marek en aves susceptibles.', 'Ave'),
('Vacuna contra Vibrio', 'Bacterias inactivadas o antigenos de especies de Vibrio, segun producto.', 'Ayuda a prevenir enfermedades bacterianas por Vibrio en determinadas especies de peces.', 'Pez'),
('Vacuna contra Aeromonas', 'Bacterias inactivadas o antigenos de Aeromonas, segun producto.', 'Ayuda a prevenir enfermedades causadas por Aeromonas en peces susceptibles.', 'Pez');